use vstd::*;
verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        n > 0 && n < list.len(),
    ensures
        new_list.len() == list.len(),
        // new_list is list[n..] ++ list[0..n]
        new_list.as_slice() == list.as_slice()[n..] + list.as_slice()[0..n],
    {
        // allocate new vector with capacity = list.len()
        let mut new_list = Vec::new();
        new_list.reserve(list.len());

        // push list[n..len]
        let len = list.len();

        let mut i = n;
        while i < len
            invariant n < len,
            invariant i >= n && i <= len,
            invariant new_list.len() == i - n,
            invariant new_list.as_slice() == list.as_slice()[n..i],
            decreases len - i,
        {
            new_list.push(list.get(i));
            i += 1;
        }

        // push list[0..n]
        let mut j = 0;
        while j < n
            invariant j >= 0 && j <= n,
            invariant new_list.len() == (len - n) + j,
            invariant new_list.as_slice() == list.as_slice()[n..len] + list.as_slice()[0..j],
            decreases n - j,
        {
            new_list.push(list.get(j));
            j += 1;
        }

        new_list
    }
}